import React, { useState, useEffect } from "react";
import { contentFactory } from "../contentFactory";
import "../styles/CreateArticlesAdmin.css";

export default function CreateArticlePage() {
  const [mode, setMode] = useState("standard"); // standard або channel
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [excerpt, setExcerpt] = useState("");
  const [category, setCategory] = useState("sport");
  const [isPremium, setIsPremium] = useState(false);
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState("");
  const [articleType, setArticleType] = useState("standard"); // для каналу: standard, no_photo, no_photo_no_comments
  const [message, setMessage] = useState("");
  const token = localStorage.getItem("token");

  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/channels/")
      .then(res => res.json())
      .then(data => setChannels(data))
      .catch(() => setChannels([]));
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");

    const createContent = contentFactory(mode, token);

    const articleData = {
      title,
      content,
      excerpt,
      is_premium: isPremium,
      ...(mode === "standard" && { category }),
      ...(mode === "channel" && { channel: selectedChannel, type: articleType }),
    };

    try {
      await createContent(articleData);
      setMessage("✅ Статтю успішно створено!");
      setTitle(""); setContent(""); setExcerpt(""); setIsPremium(false); setSelectedChannel(""); setArticleType("standard");
    } catch (err) {
      console.error(err);
      setMessage("❌ Не вдалося створити статтю");
    }
  };

  return (
    <div className="create-article-container">
      <h2>Створити статтю</h2>
      <form onSubmit={handleSubmit}>
        <label>
          Тип:
          <select value={mode} onChange={e => setMode(e.target.value)}>
            <option value="standard">Звичайна стаття</option>
            <option value="channel">Стаття для каналу</option>
          </select>
        </label>

        <input type="text" placeholder="Заголовок" value={title} onChange={e => setTitle(e.target.value)} required />
        <textarea placeholder="Контент" value={content} onChange={e => setContent(e.target.value)} required />
        <textarea placeholder="Короткий опис" value={excerpt} onChange={e => setExcerpt(e.target.value)} />

        {mode === "standard" && (
          <>
            <label>
              Категорія:
              <select value={category} onChange={e => setCategory(e.target.value)}>
                <option value="sport">Спорт</option>
                <option value="fashion">Мода</option>
                <option value="News">Новини</option>
              </select>
            </label>
            <label>
              <input type="checkbox" checked={isPremium} onChange={e => setIsPremium(e.target.checked)} /> Преміум
            </label>
          </>
        )}

        {mode === "channel" && (
          <>
            <label>
              Канал:
              <select value={selectedChannel} onChange={e => setSelectedChannel(e.target.value)}>
                <option value="">-- Оберіть канал --</option>
                {channels.map(ch => <option key={ch.id} value={ch.id}>{ch.name}</option>)}
              </select>
            </label>
            <label>
              Тип статті:
              <select value={articleType} onChange={e => setArticleType(e.target.value)}>
                <option value="standard">Стандартна</option>
                <option value="no_photo">Без фото</option>
                <option value="no_photo_no_comments">Без фото та коментарів</option>
              </select>
            </label>
          </>
        )}

        <button type="submit">Створити</button>
      </form>
      {message && <p>{message}</p>}
    </div>
  );
}
